mapper.select:
/* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.selectAptComplexList */
SELECT ac.apt_cmplex_no AS aptCmplexNo /** 아파트단지번호 */ , ac.apt_cmplex_nm AS aptCmplexNm /** 아파트단지명 */
/* 공급 세대수 → CENTER_ANN_BOARD_POST에 저장하지 않는다. → APT_UNIT에 동별 세대수가 있으면 합산하고, 없으면 APT_COMPLEX.UNIT_CNT 값을 사용한다. */ , NVL(( SELECT SUM(NVL(au.unit_cnt, 0)) FROM apt_unit au WHERE au.apt_cmplex_no = ac.apt_cmplex_no ), NVL(ac.unit_cnt, 0)) AS unitCnt
FROM apt_complex ac
ORDER BY ac.apt_cmplex_nm

/* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.selectAnnouncement */
SELECT cap.ann_no AS annNo , cap.board_no AS boardNo , cbi.board_nm AS boardNm , cbi.board_ty_cd AS boardTyCd , cap.apt_cmplex_no AS aptCmplexNo , ac.apt_cmplex_nm AS aptCmplexNm , cap.ttl AS ttl , cap.cn AS cn , cap.wrtr_id AS wrtrId , cap.top_fix_yn AS topFixYn , TO_CHAR(cap.pblanc_bgng_dt, 'YYYY-MM-DD') AS pblancBgngDt , TO_CHAR(cap.pblanc_end_dt, 'YYYY-MM-DD') AS pblancEndDt , TO_CHAR(cap.rcrt_bgng_dt, 'YYYY-MM-DD') AS rcrtBgngDt , TO_CHAR(cap.rcrt_end_dt, 'YYYY-MM-DD') AS rcrtEndDt , TO_CHAR(cap.reg_dttm, 'YYYY-MM-DD') AS regDttm , TO_CHAR(cap.mdf_dttm, 'YYYY-MM-DD') AS mdfDttm , NVL(cap.inq_cnt, 0) AS inqCnt , NVL(cap.del_yn, 'N') AS delYn , cap.atch_file_id AS atchFileId
/* 공급세대수 → 공고 테이블에 저장하지 않고 단지/동 테이블에서 계산. */ , NVL(( SELECT SUM(NVL(au.unit_cnt, 0)) FROM apt_unit au WHERE au.apt_cmplex_no = cap.apt_cmplex_no ), NVL(ac.unit_cnt, 0)) AS unitCnt
/* 제출서류명 → 현재 공고와 직접 연결 가능한 첨부파일명 표시. */ , ( SELECT LISTAGG(af.file_og_name, ', ') WITHIN GROUP (ORDER BY af.file_sort_order, af.file_og_name) FROM attach_file af WHERE af.file_group_no = cap.atch_file_id ) AS sbmsnDocNm
, CASE WHEN cap.rcrt_bgng_dt IS NULL OR cap.rcrt_end_dt IS NULL THEN '-' WHEN TRUNC(SYSDATE) < TRUNC(cap.rcrt_bgng_dt) THEN '예정' WHEN TRUNC(SYSDATE) > TRUNC(cap.rcrt_end_dt) THEN '마감' ELSE '진행중' END AS statusNm
FROM center_ann_board_post cap
LEFT JOIN center_board_instance cbi ON cap.board_no = cbi.board_no
LEFT JOIN apt_complex ac ON cap.apt_cmplex_no = ac.apt_cmplex_no
WHERE cap.ann_no = #{annNo} AND NVL(cap.del_yn, 'N') = 'N'

mapper.update:
        /* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.updateAnnouncement */

        UPDATE center_ann_board_post cap
        SET cap.apt_cmplex_no = #{aptCmplexNo}
        , cap.ttl = #{ttl}
        , cap.cn = #{cn}
        , cap.top_fix_yn = NVL(#{topFixYn, jdbcType=VARCHAR}, 'N')
        , cap.pblanc_bgng_dt = TO_DATE(#{pblancBgngDt}, 'YYYY-MM-DD')
        , cap.pblanc_end_dt = TO_DATE(#{pblancEndDt}, 'YYYY-MM-DD')
        , cap.rcrt_bgng_dt = TO_DATE(#{rcrtBgngDt}, 'YYYY-MM-DD')
        , cap.rcrt_end_dt = TO_DATE(#{rcrtEndDt}, 'YYYY-MM-DD')
        , cap.atch_file_id = #{atchFileId, jdbcType=VARCHAR}
        , cap.mdf_dttm = SYSDATE
        WHERE cap.ann_no = #{annNo}

        /* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.deleteAnnouncement */

        UPDATE center_ann_board_post cap
        SET cap.del_yn = 'Y'
        , cap.mdf_dttm = SYSDATE
        WHERE cap.ann_no = #{annNo}
